INSERT INTO tetrilogic_templates VALUES ('tetrilogic-v2-1',2,JSON '{"level":1,"templateId":"tetrilogic-v2-1","version":2,"title":"Primer encuentro","description":"Coloca las 3 piezas y cumple todos los conteos de filas y columnas. Cubre las celdas marcadas, respeta el orden y los contactos indicados; pueden quedar espacios vacíos.","cognitiveDimension":"Reconocimiento de patrones","boardSize":{"rows":4,"cols":4},"blockedCells":[{"x":2,"y":3}],"constraints":[{"line":0,"orientation":"row","targetCount":3},{"line":1,"orientation":"row","targetCount":3},{"line":2,"orientation":"row","targetCount":3},{"line":3,"orientation":"row","targetCount":3},{"line":0,"orientation":"column","targetCount":3},{"line":1,"orientation":"column","targetCount":4},{"line":2,"orientation":"column","targetCount":1},{"line":3,"orientation":"column","targetCount":4}],"inventory":[{"id":"i1","type":"I"},{"id":"s1","type":"S"},{"id":"o1","type":"O"}],"requiredCells":[{"x":1,"y":3}],"precedences":[{"before":"i1","after":"s1"}],"contacts":[{"first":"i1","second":"s1"}],"orientations":[],"referenceMoves":4,"hints":{"general":"En este tablero, la fila 1 necesita 3 celdas y la columna 3 necesita 1. Compara estos conteos antes de colocar las piezas.","specific":"Coloca I1 antes de S1. Al terminar deben compartir un lado. La celda marcada en fila 4, columna 2 debe estar ocupada; no tiene que ser por una pieza concreta."}}') ON CONFLICT DO NOTHING;
